"use client";
import React, { useEffect, useState } from "react";
import { navlinks } from "../utils/navlinks";
import Link from "next/link";
import clsx from "clsx";
import { LogIn, Menu } from "lucide-react";
import { useGlobalContext } from "../providers/GlobalProvider";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import Image from "next/image";
import Logo2 from "@/public/logo2.svg";

const Header = () => {
  const pathname = usePathname();
  const { isOpen, setIsOpen } = useGlobalContext();
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 30);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <div
      className={cn(
        "border-b-[1px] border-[#f1f1f1] p-[10px] text-white hover:bg-white hover:text-black group/2 fixed top-0 left-0 right-0 z-10 transition-colors duration-300",
        scrolled ? "bg-white text-black shadow-md" : "bg-transparent text-white"
      )}
    >
      <div className="flex justify-between items-center gap-4">
        <Image
          src={Logo2}
          alt="Logo"
          width={100}
          height={100}
          className={cn(
            "w-[250px] h-[100px] [filter:brightness(100)] group-hover/2:filter-none",
            scrolled ? "filter-none" : "filter-brightness-0"
          )}
        />
        <ul className="hidden lg:flex lg:gap-20 lg:justify-between lg:items-center">
          {navlinks.map((link) => (
            <li
              key={link.href}
              className={cn(
                "relative text-[16px] font-medium transition-all cursor-pointer duration-300 hover:scale-105 group"
              )}
            >
              <Link href={link.href} className="hover:text-[#3385FF]">
                {link.label}
              </Link>
              <div
                className={cn(
                  "absolute top-8 left-0 h-[2px] w-full",
                  pathname === link.href && "bg-white"
                )}
              >
                <div className="h-full w-0 group-hover:bg-[#3385FF] group-hover:w-full transition-all duration-1000 ease-in-out"></div>
              </div>
            </li>
          ))}
        </ul>
        <div className="flex gap-4 items-center">
          <a
            href="https://docs.google.com/forms/d/e/1FAIpQLScYqn18pKTS3aFyYZx-eQjSlOVcigEV9E_-vyAkmDDe11OAuw/viewform"
            target="_blank"
            className={clsx(
              "capitalize inline-block w-fit border-[1px] border-[#aaa] px-[13px] py-[7px] rounded-[50px] cursor-pointer hover:transition-all hover:duration-300 hover:scale-105 hover:bg-[#3385FF] hover:text-white"
            )}
          >
            <span className="flex items-center gap-[5px] text-[13px] font-normal leading-[16px]">
              Submit Paper
            </span>
          </a>
          <button
            className={clsx(
              "capitalize inline-block w-fit border-[1px] border-[#aaa] px-[13px] py-[7px] rounded-[50px] cursor-pointer transition-all duration-300 hover:scale-105 hover:bg-[#3385FF] hover:text-white"
            )}
          >
            <Link
              href="/contact-us"
              className="flex items-center gap-[5px] text-[13px] font-normal leading-[16px]"
            >
              <LogIn className="w-[13px] h-[13px]" />
              Contact us
            </Link>
          </button>

          <Menu
            className={clsx(
              "block lg:hidden w-[24px] h-[24px] cursor-pointer hover:scale-115 transition-all duration-300 ease-in-out group-hover/2:text-black",
              isOpen ? "hidden" : "block",
              scrolled ? "text-black" : "text-white"
            )}
            onClick={() => setIsOpen(!isOpen)}
          />
        </div>
      </div>
    </div>
  );
};

export default Header;

